int is_prime(int n)
{
    int i;
    if (n < 2) return 0;
    for (i = 2; i * i <= n; i++)
        if (n % i == 0) return 0;
    return 1;
}
int main()
{
    char s[16];
    int len, i, j, k, num, m, out[45], cnt = 0, found;
    scanf("%s", s);
    len = strlen(s);
    for (k = 1; k <= len; k++)
        for (i = 0; i + k <= len; i++)
        {
            num = 0;
            for (j = i; j < i + k; j++) num = num * 10 + s[j] - '0';
            if (is_prime(num))
            {
                found = 0;
                for (m = 0; m < cnt; m++)
                    if (out[m] == num) found = 1;
                if (!found) out[cnt++] = num;
            }
        }
    for (m = 0; m < cnt; m++)
        printf("%d%c", out[m], m == cnt - 1 ? '\n' : ' ');
    if (cnt == 0) printf("\n");
    return 0;
}

