#include <stdio.h>
int gcd(int a, int b)
{
    while (b != 0)
    {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}
int main()
{
    int a, b, g;
    scanf("%d%d", &a, &b);
    g = gcd(a, b);
    printf("gcd=%d,lcm=%d\n", g, a / g * b);
    return 0;
}

