#include <stdio.h>
int VerifyCode(char n[])
{
    int w[18] = {7,9,10,5,8,4,2,1,6,3,7,9,10,5,8,4,2,1};
    int i, a, sum = 0;
    for (i = 0; i < 18; i++)
    {
        if (i == 17 && (n[i] == 'X' || n[i] == 'x')) a = 10;
        else a = n[i] - '0';
        sum += a * w[i];
    }
    return sum % 11 == 1;
}
