    else printf("False\n");
    return 0;
}

#include <stdio.h>
#include <math.h>
int main()
{
    int n, i, a[1000];
    double avg = 0, d = 0;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
    {
        scanf("%d", &a[i]);
        avg += a[i];
    }
    avg /= n;
    for (i = 0; i < n; i++)
        d += (a[i] - avg) * (a[i] - avg);
    d /= n;
