        printf("%f\n", (a[i] - avg) / sqrt(d));
    return 0;
}

#include <stdio.h>
void stat(int a[], int n, int *pmax, int *pmin, double *pavg)
{
    int i, sum = 0;
    *pmax = a[0];
    *pmin = a[0];
    for (i = 0; i < n; i++)
    {
        if (a[i] > *pmax) *pmax = a[i];
        if (a[i] < *pmin) *pmin = a[i];
        sum += a[i];
    }
    *pavg = 1.0 * sum / n;
}
int main()
{
    int a[100], n, i, max, min;
    double avg;
    scanf("%d", &n);
    for (i = 0; i < n; i++) scanf("%d", &a[i]);
    stat(a, n, &max, &min, &avg);
    printf("max=%d,min=%d,avg=%.2f\n", max, min, avg);
    return 0;
}

