#include <stdio.h>
struct student
{
    char name[20];
    int s[3];
    double avg;
};
int main()
{
    struct student stu[50], *p, *best;
    int n, i;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
    {
        p = &stu[i];
        scanf("%s%d%d%d", p->name, &p->s[0], &p->s[1], &p->s[2]);
        p->avg = (p->s[0] + p->s[1] + p->s[2]) / 3.0;
        printf("%s %.2f\n", p->name, p->avg);
    }
    best = &stu[0];
    for (i = 1; i < n; i++)
        if (stu[i].avg > best->avg) best = &stu[i];
    printf("%s %.2f\n", best->name, best->avg);
    return 0;
}

