void convert(char ch, char *s)
{
    int i = 7, k = 0, n = ch;
    while (n > 0)
    {
        s[i--] = n % 2 + '0';
        if (n % 2 == 1) k++;
        n /= 2;
    }
    while (i >= 1) s[i--] = '0';
    s[0] = (k % 2 == 0) ? '1' : '0';
    s[8] = '\0';
}
