#include <stdio.h>
void strmoveleft(char a[], int n)
{
    int len = 0, i, j;
    char c;
    while (a[len] != '\0')
        len++;
    if (len == 0)
        return;
    n = n % len;
    for (j = 0; j < n; j++)
    {
        c = a[0];
        for (i = 0; i < len - 1; i++)
            a[i] = a[i + 1];
        a[len - 1] = c;
    }
}
