}

#include <stdio.h>
float legendre(int n, float x)
{
    if (n == 0)
        return 1;
    if (n == 1)
        return x;
    return ((2 * n - 1) * x * legendre(n - 1, x) - (n - 1) * legendre(n - 2, x)) / n;
}
int main(void)
{
    int n;
    float x;
    scanf("%d%f", &n, &x);
    printf("%.4f\n", legendre(n, x));
    return 0;
}

