void minmax(int a[], int n, int *pmin, int *pmax)
{
    int i;
    *pmin = *pmax = a[0];
    for (i = 1; i < n; i++) {
        if (a[i] < *pmin) *pmin = a[i];
        if (a[i] > *pmax) *pmax = a[i];
    }
}

