int main(void)
{
    int **a, m, n, i, j, sum;
    scanf("%d%d", &m, &n);
    a = (int **)malloc(m * sizeof(int *));
    if (a == NULL) return 1;
    for (i = 0; i < m; i++) {
        a[i] = (int *)malloc(n * sizeof(int));
        if (a[i] == NULL) return 1;
    }
    for (i = 0; i < m; i++)
        for (j = 0; j < n; j++)
            scanf("%d", &a[i][j]);
