    for (i = 0; i < 3; i++) a[i] = i + 1;

    t = (int *)realloc(a, 6 * sizeof(int));
    if (t == NULL) { free(a); return 1; }
    a = t;
    for (i = 3; i < 6; i++) a[i] = i + 1;

    for (i = 0; i < 6; i++) sum += a[i];
    printf("sum=%d, capacity=6\n", sum);
    free(a);
    return 0;
}

