#include <stdio.h>

int is_prime(int x)
{
    int i;
    if (x < 2) return 0;
    for (i = 2; i * i <= x; i++)
        if (x % i == 0) return 0;
    return 1;
}

int is_pal(int x)
{
    int t = x, r = 0;
    while (t > 0) { r = r * 10 + t % 10; t /= 10; }
    return r == x;
}

int main(void)
{
    int m, n, i, found = 0;
    scanf("%d%d", &m, &n);
    for (i = m; i <= n; i++) {
        if (is_prime(i) && is_pal(i)) { printf("%d\n", i); found = 1; }
    }
    if (!found) printf("none\n");
    return 0;
}

