#include <stdio.h>

void quick(int a[], int left, int right)
{
    int i = left, j = right;
    int key = a[left];

    if (left >= right)
        return;

    while (i < j)
    {
        while (i < j && a[j] >= key)
            j--;
        a[i] = a[j];
        while (i < j && a[i] <= key)
            i++;
        a[j] = a[i];
    }
    a[i] = key;

    quick(a, left, i - 1);
    quick(a, i + 1, right);
}

int main(void)
{
    int a[1005], n, i;

    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%d", &a[i]);

    quick(a, 0, n - 1);

    for (i = 0; i < n; i++)
        printf(i ? " %d" : "%d", a[i]);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct Node
{
    int data;
    struct Node *next;
} Node;

int main(void)
{
    int n, x, i, v;
    Node *head = NULL, *tail = NULL, *p, *pre;

    scanf("%d %d", &n, &x);
    for (i = 0; i < n; i++)
    {
        scanf("%d", &v);
        p = (Node *)malloc(sizeof(Node));
        p->data = v;
        p->next = NULL;
        if (head == NULL)
            head = tail = p;
        else
        {
            tail->next = p;
            tail = p;
        }
    }

    pre = NULL;
    p = head;
    while (p != NULL && p->data != x)
    {
        pre = p;
        p = p->next;
    }
    if (p != NULL)
    {
        if (pre == NULL)
            head = p->next;
        else
            pre->next = p->next;
        free(p);
    }

    for (p = head; p != NULL; p = p->next)
        printf(p == head ? "%d" : " %d", p->data);
    printf("\n");
    return 0;
}

#include <stdio.h>

int isLeap(int y)
{
    return (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0);
}

int dayOfYear(int y, int m, int d)
{
    int md[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int i, sum = 0;

    for (i = 0; i < m - 1; i++)
        sum += md[i];
    sum += d;
    if (m > 2 && isLeap(y))
        sum++;
    return sum;
}

int main(void)
{
    int y, m, d, i, total = 0;

    scanf("%d %d %d", &y, &m, &d);

    for (i = 2010; i < y; i++)
        total += isLeap(i) ? 366 : 365;
    total += dayOfYear(y, m, d) - 1;

    printf("%s\n", (total % 5) < 3 ? "打鱼" : "晒网");
    return 0;
}

